import { useId, useState, type KeyboardEvent, type ReactNode } from 'react';
import { IconChevronRight } from '../../../icons/chevron-right';
import { useControllableState } from '../../../primitives/use-controllable-state';
import { Button } from '../../actions/button/Button';
import './carousel-3d.css';

export interface CarouselSlide {
  id: string;
  /** Names the slide for the slide picker and for assistive technology. */
  label: string;
  content: ReactNode;
}

export interface Carousel3DProps {
  /** Names the carousel, for example "Harbour guides". */
  label: string;
  slides: readonly CarouselSlide[];
  index?: number;
  defaultIndex?: number;
  onIndexChange?: (index: number) => void;
  className?: string;
}

/**
 * A ring of slides in CSS 3D that you turn with buttons, the arrow keys or the slide picker.
 * Follows the WAI-ARIA carousel pattern. It never turns by itself, so there is nothing to
 * pause. No WebGL.
 */
export function Carousel3D({
  label,
  slides,
  index,
  defaultIndex = 0,
  onIndexChange,
  className,
}: Carousel3DProps) {
  const [current, setCurrent] = useControllableState({
    value: index,
    defaultValue: defaultIndex,
    onChange: onIndexChange,
  });
  // A running count of turns, so the ring always takes the short way round.
  const [turns, setTurns] = useState(current);
  const id = useId();
  const n = slides.length;
  // Announce slide changes only after the first one the person makes.
  const [live, setLive] = useState(false);

  const go = (step: number) => {
    setLive(true);
    setTurns((t) => t + step);
    setCurrent((c) => (((c + step) % n) + n) % n);
  };
  const goTo = (target: number) => {
    const forward = (((target - current) % n) + n) % n;
    go(forward <= n / 2 ? forward : forward - n);
  };

  const onKeyDown = (event: KeyboardEvent<HTMLElement>) => {
    if (event.key === 'ArrowRight') {
      event.preventDefault();
      go(1);
    } else if (event.key === 'ArrowLeft') {
      event.preventDefault();
      go(-1);
    }
  };

  const angle = 360 / n;

  return (
    // Arrow keys turn the ring while focus is anywhere inside the carousel region.
    // eslint-disable-next-line jsx-a11y/no-noninteractive-element-interactions
    <section
      className={['atl-carousel', className].filter(Boolean).join(' ')}
      aria-roledescription="carousel"
      aria-label={label}
      onKeyDown={onKeyDown}
      style={{ '--atl-n': n, '--atl-turn': turns } as React.CSSProperties}
    >
      <div className="atl-carousel__controls">
        <Button
          size="s"
          icon={<IconChevronRight style={{ rotate: '180deg' }} />}
          aria-label="Previous slide"
          aria-controls={`${id}-ring`}
          onClick={() => go(-1)}
        />
        <div className="atl-carousel__picker" role="group" aria-label="Choose a slide">
          {slides.map((slide, i) => (
            <button
              key={slide.id}
              type="button"
              className="atl-carousel__dot"
              aria-label={slide.label}
              aria-current={i === current ? 'true' : undefined}
              aria-controls={`${id}-ring`}
              onClick={() => goTo(i)}
            />
          ))}
        </div>
        <Button
          size="s"
          icon={<IconChevronRight />}
          aria-label="Next slide"
          aria-controls={`${id}-ring`}
          onClick={() => go(1)}
        />
      </div>
      <div className="atl-carousel__viewport">
        <div
          id={`${id}-ring`}
          className="atl-carousel__ring"
          aria-live={live ? 'polite' : 'off'}
          aria-atomic="false"
        >
          {slides.map((slide, i) => {
            const active = i === current;
            return (
              <div
                key={slide.id}
                className="atl-carousel__slide"
                role="group"
                aria-roledescription="slide"
                aria-label={`${i + 1} of ${n}: ${slide.label}`}
                aria-hidden={active ? undefined : true}
                inert={!active}
                data-active={active || undefined}
                style={
                  {
                    '--atl-i': i,
                    transform: `rotateY(${i * angle}deg) translateZ(var(--atl-radius))`,
                  } as React.CSSProperties
                }
              >
                {slide.content}
              </div>
            );
          })}
        </div>
      </div>
    </section>
  );
}

@layer atlas.components {
  .atl-carousel {
    --atl-slide-w: 15rem;
    --atl-radius: calc(var(--atl-slide-w) * 0.5 / tan(180deg / var(--atl-n)) + 1.5rem);
    display: grid;
    gap: var(--space-m);
    width: 100%;
  }

  .atl-carousel__viewport {
    height: 15rem;
    perspective: 1100px;
    overflow: hidden;
  }

  .atl-carousel__ring {
    position: relative;
    width: var(--atl-slide-w);
    height: 100%;
    margin: 0 auto;
    transform-style: preserve-3d;
    transform: translateZ(calc(-1 * var(--atl-radius)))
      rotateY(calc(var(--atl-turn) * -360deg / var(--atl-n)));
    transition: transform var(--dur-voyage) var(--ease-drift);
  }

  .atl-carousel__slide {
    position: absolute;
    inset: 0;
    display: grid;
    padding: var(--space-m);
    border-radius: var(--radius-panel);
    background: var(--shoal);
    box-shadow: inset 0 0 0 1px color-mix(in oklch, var(--isobath) 55%, transparent);
    backface-visibility: hidden;
    opacity: 0.45;
    transition: opacity var(--dur-glide) var(--ease-anchor);
  }

  .atl-carousel__slide[data-active] {
    opacity: 1;
    box-shadow:
      inset 0 0 0 1px var(--edge),
      0 18px 40px -20px var(--shadow-tint);
  }

  .atl-carousel__controls {
    display: flex;
    align-items: center;
    justify-content: center;
    gap: var(--space-s);
  }

  .atl-carousel__picker {
    display: flex;
    gap: 2px;
  }

  /* A 24px target around a small dot. */
  .atl-carousel__dot {
    display: grid;
    place-items: center;
    width: 24px;
    height: 24px;
    padding: 0;
    border: 0;
    border-radius: 50%;
    background: none;
  }

  .atl-carousel__dot::after {
    content: '';
    width: 8px;
    height: 8px;
    border-radius: 50%;
    box-shadow: inset 0 0 0 1.5px var(--ink-soft);
  }

  .atl-carousel__dot[aria-current='true']::after {
    width: 10px;
    height: 10px;
    background: var(--chart-magenta);
    box-shadow: none;
  }

  @media (prefers-reduced-motion: reduce) {
    :root:not([data-motion='full']) .atl-carousel__ring {
      transition: none;
    }
  }

  :root[data-motion='reduce'] .atl-carousel__ring {
    transition: none;
  }
}
